INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('16373f39-c20d-4ca5-97e1-f294dcc349d4', '150f78d3-019b-40c0-962e-a83576309ea5', 6, 'A Alegria Profunda', NULL, '{"intro": "A alegria crist\u00e3 \u00e9 uma decis\u00e3o, n\u00e3o um sentimento passageiro.", "prayer": "Agrade\u00e7a por 5 pequenas alegrias do dia.", "practice": "Sorria para tr\u00eas estranhos hoje.", "reflection": "Um cora\u00e7\u00e3o triste \u00e9 um alvo f\u00e1cil para o mal.", "journal_prompt": "Onde voc\u00ea busca a sua alegria?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;